namespace Team5.qPCR
{
    public static class QpcrTeachingContent
    {
        public static string Explain(QpcrLessonState state) => state switch
        {
            QpcrLessonState.InspectPlateId => "WHY CHECK THE ID?\nA plate has 96 wells: rows A-H and columns 1-12. The label must match the handoff record so results are assigned to the correct experiment. Our record is T4-QPCR-2026-05. If it does not match, stop and resolve the discrepancy; do not guess.",
            QpcrLessonState.InspectA1Marker => "WHY FIND A1?\nA1 means row A, column 1. It fixes the direction of the plate map. Rotating the plate 180 degrees puts samples under the wrong well names. Find the red corner now, and match it to the red corner on the holder during loading.",
            QpcrLessonState.InspectOpticalSeal => "WHY AN OPTICAL SEAL?\nA flat, intact seal keeps reactions enclosed and reduces evaporation during heating. It must transmit the light used for fluorescence measurements. Check edges and avoid touching the optical surface. If the seal is damaged or lifting, resolve it before loading.",
            QpcrLessonState.InspectBubbles => "WHY CHECK BUBBLES?\nBubbles can disturb optical readings. Team 5 receives an already prepared and sealed plate. If bubbles are present, follow the approved brief centrifugation procedure with a balanced plate centrifuge before loading. This lesson's plate is already ready; do not open it or remix its reactions.",
            QpcrLessonState.ReturnPlate => "WHY RETURN THE PLATE?\nPut the sealed plate flat in its clean handoff position while preparing the machine. Carry it by its edges. A floor drop can damage or compromise it: the simulator leaves it on the floor and blocks loading until Reset provides a fresh training plate.",
            QpcrLessonState.PowerOn => "WHY POWER ON?\nThe electronics, optics and temperature controls must be ready before loading. A real instrument may perform startup checks; follow its manual. This simulator uses a short startup sound and welcome screen. The power button does not start amplification.",
            QpcrLessonState.OpenDrawer => "WHY OPEN THE COMPARTMENT?\nThe plate holder exposes the thermal block, which heats and cools the reactions. Wait for the drawer to stop moving. Never force it. Keep the sealed plate level and identify the holder's red A1 corner before inserting it.",
            QpcrLessonState.LoadPlate => "WHY ALIGN AND SEAT?\nMatch both A1 corners and lower the plate flat into the holder. Correct seating provides contact with the temperature-controlled block and preserves the well map. Release Grip only when the guide turns green. Amber means misaligned; red explains a rejected attempt.",
            QpcrLessonState.CloseDrawer => "WHY CLOSE THE COMPARTMENT?\nThe plate must stay securely seated before the heated lid and thermal programme operate. The lid helps limit condensation; the enclosure supports consistent temperature and optical measurement. The simulator locks this action until seating succeeds.",
            QpcrLessonState.ConfigureProtocol or QpcrLessonState.ValidateProtocol => "WHY PROGRAM THE RUN?\nThe programme controls temperature, duration and fluorescence collection. Enter the temperatures AND hold times. This is a specified teaching assay using SYBR Green, not a universal recipe. A real assay requires validated primer, reagent and instrument instructions. Select a field for its explanation.",
            QpcrLessonState.StartRun => "WHY VALIDATE BEFORE START?\nConfirm identity, seal, orientation, seating, closed drawer and every programme entry. The run repeatedly heats and cools reactions and measures fluorescence. A wrong setting can cause failed or misleading results. Real experiments also require appropriate controls and replicates.",
            QpcrLessonState.ObserveAmplification => "WHAT IS HAPPENING?\nAt 95 degrees C the DNA strands separate. At 60 degrees C primers bind; fluorescence is collected. At 72 degrees C the polymerase extends DNA. SYBR Green reports double-stranded DNA, including unwanted products. Watch the blue positive control, green teaching sample and orange NTC. Time is accelerated and all curves are synthetic teaching data.",
            QpcrLessonState.InterpretResults => "HOW DO WE READ THE RESULT?\nCq (also called Ct) is the cycle at which fluorescence crosses a chosen threshold above background. The positive control should amplify; the NTC contains no template and should not show target amplification. Inspect melt peaks for unexpected products. One peak supports consistency but does not prove target identity. These checks do not replace full assay acceptance criteria.",
            QpcrLessonState.Complete => "WHAT HAVE YOU LEARNED?\nYou checked the handoff, aligned and loaded a sealed plate, programmed temperatures and hold times, monitored fluorescence and interpreted controls, Cq and a melt peak. Keep post-PCR plates sealed to reduce carryover contamination. Use the laboratory's validated procedure for disposal and real experiments.",
            _ => "qPCR copies a selected DNA region while measuring fluorescence during cycling. Team 5 starts with a prepared 96-well plate. Your task is to inspect it, load it, programme the instrument, run the lesson and explain the result. Use WHY at any step to learn the reason behind the action."
        };

        public static string Explain(QpcrProtocolParameter p) => p switch
        {
            QpcrProtocolParameter.ReactionVolume => "Reaction volume is the amount in each well, not the whole plate. Enter 20 microlitres to match this prepared plate and the instrument's thermal settings.",
            QpcrProtocolParameter.LidTemperature => "The heated lid is set to 105 degrees C in this lesson. It helps limit condensation above the reactions. The lid temperature differs from the block temperature.",
            QpcrProtocolParameter.InitialDenaturation or QpcrProtocolParameter.InitialHoldSeconds => "The initial hold is 95 degrees C for 120 seconds. It separates DNA strands; activation requirements depend on the chosen polymerase. Use the validated reagent protocol.",
            QpcrProtocolParameter.AmplificationCycles => "Repeat the thermal sequence 35 times. Fluorescence is sampled each cycle. More cycles do not automatically mean a better or more reliable result.",
            QpcrProtocolParameter.Denaturation or QpcrProtocolParameter.DenaturationSeconds => "Denaturation is 95 degrees C for 15 seconds in each cycle. Heating separates the DNA strands so primers can bind in the next stage.",
            QpcrProtocolParameter.Annealing or QpcrProtocolParameter.AnnealingSeconds => "Annealing is 60 degrees C for 30 seconds in this teaching assay. Primers bind to complementary DNA. The appropriate temperature depends on primer design and assay validation.",
            QpcrProtocolParameter.Extension or QpcrProtocolParameter.ExtensionSeconds => "Extension is 72 degrees C for 30 seconds here. The DNA polymerase extends the primers to make new strands. Required time depends on the enzyme and product length.",
            QpcrProtocolParameter.FluorescenceAcquisition => "Acquire fluorescence at 60 degrees C during annealing in each cycle. Comparing readings at the same stage provides a consistent amplification trace.",
            QpcrProtocolParameter.MeltCurveStart or QpcrProtocolParameter.MeltCurveEnd or QpcrProtocolParameter.TemperatureIncrement => "After amplification, increase temperature from 65 to 95 degrees C in 0.5-degree steps. DNA melting changes SYBR fluorescence. A derivative peak shows a melting transition; extra peaks can indicate unwanted products. Dwell time follows the real instrument's method.",
            QpcrProtocolParameter.PostRunHold => "The block holds at 4 degrees C after the programme in this lesson. This is a short post-run hold, not a long-term storage method. Keep amplified plates sealed and follow the disposal procedure.",
            _ => "Use the approved training protocol."
        };
    }
}
